/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=activity, operation=delete
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Delete an activity */
export type PipedriveV2ActivityDeleteParams = {
  resource: 'activity';
  operation: 'delete';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the activity to delete
 * @default 0
 */
    activityId?: number | Expression<number>;
};

export type PipedriveV2ActivityDeleteNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2ActivityDeleteParams>;
};